import Foundation
import XCTest
@testable import ColorComposerCore

/// Solver parity against the golden-vector corpus produced by the Elixir
/// `color_matching` service (`priv/parity/v1/corpus.json`, generated by
/// `ColorMatching.Parity.Corpus` — see viamin/color_matching#111).
///
/// The corpus is committed byte-for-byte at
/// `Tests/ColorComposerCoreTests/Fixtures/parity/v1/corpus.json`; see
/// `docs/solver-parity-corpus.md` for the refresh procedure. Every scenario
/// replays the same inputs through `WeightedSquaredErrorScorer` (score level)
/// and `CompositionSolver` (selection level) and asserts the results match the
/// corpus expectations *exactly* — ties, exclusions, and channel weights
/// included. The corpus numbers are exact binary fractions, so exact `Double`
/// equality is meaningful: any divergence in tie-breaking, exclusion policy,
/// or weight handling shows up as a parity failure here.
final class SolverParityCorpusTests: XCTestCase {
    private let scorer = WeightedSquaredErrorScorer()

    // MARK: - Corpus loading

    private func loadCorpus(file: StaticString = #filePath, line: UInt = #line) throws -> ParityCorpus {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/parity/v1/corpus.json")
        do {
            return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: url))
        } catch {
            XCTFail("Failed to load solver parity corpus at \(url.path): \(error)", file: file, line: line)
            throw error
        }
    }

    // MARK: - Provenance contract

    /// The corpus must declare the exact scorer/selection/policy semantics the
    /// Swift implementation mirrors; a corpus for a different scorer or a new
    /// algorithm version must be reviewed before being committed here.
    func testCorpusDeclaresMirroredSemantics() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")
        XCTAssertEqual(corpus.algorithmVersion, 1)
    }

    /// The corpus light-source list must match `LightingCondition` exactly,
    /// including order — channel order is part of the shared contract.
    func testCorpusLightSourcesMatchLightingCondition() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.lightSources, LightingCondition.all.map(\.rawValue))
    }

    /// The committed corpus must keep covering every behavior class the parity
    /// suite exists to police: outright wins, ties, missing-measurement
    /// exclusions (candidate and target), zero-weight channels, unknown weight
    /// keys, and exact matches. A refresh that drops a scenario category must
    /// fail here rather than silently narrow parity coverage.
    func testCorpusCoversEveryBehaviorClass() throws {
        let corpus = try loadCorpus()
        let scenarios = corpus.scenarios

        XCTAssertGreaterThanOrEqual(scenarios.count, 12)
        XCTAssertTrue(
            scenarios.contains { $0.expected.tieBroke == true },
            "corpus must include at least one tie scenario"
        )
        XCTAssertTrue(
            scenarios.contains { $0.expected.selectedIndex == nil },
            "corpus must include at least one no-selection scenario"
        )
        XCTAssertTrue(
            scenarios.contains { $0.expected.scores.contains { $0.score.isExcluded } },
            "corpus must include at least one excluded candidate"
        )
        XCTAssertTrue(
            scenarios.contains { $0.expected.error == 0 },
            "corpus must include at least one exact-match scenario"
        )
        XCTAssertTrue(
            scenarios.contains { scenario in
                scenario.weights.keys.contains { LightingCondition(rawValue: $0) == nil }
            },
            "corpus must include at least one scenario with an unknown weight key"
        )
        XCTAssertTrue(
            scenarios.contains { !$0.expected.tiedIndices.isEmpty && $0.expected.tieBroke == false },
            "corpus must include a distinct-error winner"
        )
    }

    // MARK: - Parity: scorer scores

    /// Every per-candidate score in every scenario must match the corpus
    /// exactly — `excluded` for unmeasured positive-weight channels, exact
    /// `Double` equality otherwise.
    func testScorerScoresMatchCorpusExactly() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let weights = scenario.weights.channelWeights
            let target = scenario.target.vector
            let palette = scenario.palette.map(\.color)

            XCTAssertEqual(
                scenario.expected.scores.count, palette.count,
                "\(scenario.id): expected scores must cover the whole palette"
            )

            for (candidateIndex, candidate) in palette.enumerated() {
                let expected = scenario.expected.scores[candidateIndex]
                XCTAssertEqual(
                    expected.index, candidateIndex,
                    "\(scenario.id): corpus scores must be in palette order"
                )
                let actual = scorer.score(candidate: candidate, target: target, weights: weights)
                switch (expected.score, actual) {
                case let (.excluded, actual):
                    XCTAssertTrue(
                        actual.isExcluded,
                        "\(scenario.id): candidate \(candidateIndex) expected excluded, got \(actual)"
                    )
                case let (.value(expectedValue), .score(actualValue)):
                    XCTAssertEqual(
                        actualValue, expectedValue,
                        "\(scenario.id): candidate \(candidateIndex) score diverged from corpus"
                    )
                case let (.value(expectedValue), actual):
                    XCTFail(
                        "\(scenario.id): candidate \(candidateIndex) expected score \(expectedValue), got \(actual)"
                    )
                }
            }
        }
    }

    // MARK: - Parity: selection, error, ties

    /// Earliest-index-wins selection recomputed from the scorer must match the
    /// corpus selection, best error, tie membership, and tie_broke flag —
    /// including the no-selection scenarios where every candidate is excluded.
    func testSelectionMatchesCorpusIncludingTies() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let weights = scenario.weights.channelWeights
            let target = scenario.target.vector
            let palette = scenario.palette.map(\.color)

            let results = palette.map { scorer.score(candidate: $0, target: target, weights: weights) }
            var bestIndex: Int?
            var bestScore: Double?
            for (index, result) in results.enumerated() {
                guard case .score(let value) = result,
                      bestScore == nil || value < bestScore! else { continue }
                bestIndex = index
                bestScore = value
            }
            let tiedIndices: [Int] = bestScore.map { best in
                results.indices.compactMap { index in
                    guard case .score(let value) = results[index], value == best else { return nil }
                    return index
                }
            } ?? []

            XCTAssertEqual(
                bestIndex, scenario.expected.selectedIndex,
                "\(scenario.id): selected index diverged from corpus"
            )
            XCTAssertEqual(
                bestScore, scenario.expected.error,
                "\(scenario.id): winning error diverged from corpus"
            )
            XCTAssertEqual(
                tiedIndices, scenario.expected.tiedIndices,
                "\(scenario.id): tie membership diverged from corpus"
            )
            XCTAssertEqual(
                scenario.expected.tieBroke, tiedIndices.count > 1,
                "\(scenario.id): tie_broke diverged from corpus"
            )

            if let selected = bestIndex {
                XCTAssertEqual(
                    palette[selected].hex, scenario.expected.selectedHexColor,
                    "\(scenario.id): selected hex diverged from corpus"
                )
            }
        }
    }

    // MARK: - Parity: solver selection path

    /// The real composition pipeline must reproduce the corpus selection:
    /// single-cell source grids built from the target vector, solved with the
    /// default `WeightedSquaredErrorScorer` fast path. Scenarios whose target
    /// is missing a positive-weight channel cannot be expressed as source
    /// grids (the solver throws `missingSourceGrid` by design) and are covered
    /// at the scorer level above.
    func testSolverSelectionPathMatchesCorpus() throws {
        let corpus = try loadCorpus()

        for scenario in corpus.scenarios {
            let weights = scenario.weights.channelWeights
            let active = weights.activeConditions
            guard !active.isEmpty else {
                XCTFail("\(scenario.id): corpus scenario must have an active channel")
                continue
            }
            guard active.allSatisfy({ scenario.target.channels[$0.rawValue] != nil }) else { continue }

            let palette = scenario.palette.map(\.color)
            var grids: [LightingCondition: BrightnessGrid] = [:]
            for condition in active {
                grids[condition] = BrightnessGrid(
                    width: 1,
                    height: 1,
                    values: [scenario.target.channels[condition.rawValue]!]
                )
            }

            let result = try CompositionSolver().solve(
                palette: palette,
                sourceGrids: grids,
                weights: weights
            )

            XCTAssertEqual(
                result.colorIndex(x: 0, y: 0), scenario.expected.selectedIndex,
                "\(scenario.id): solver selection diverged from corpus"
            )
            if let error = scenario.expected.error {
                XCTAssertEqual(
                    result.error(x: 0, y: 0), error,
                    "\(scenario.id): solver error diverged from corpus"
                )
            } else {
                XCTAssertEqual(result.error(x: 0, y: 0), .infinity, "\(scenario.id): expected no match")
            }
            XCTAssertEqual(
                result.excludedCandidateCount,
                scenario.expected.scores.filter { $0.score.isExcluded }.count,
                "\(scenario.id): excluded-candidate count diverged from corpus"
            )
        }
    }
}

// MARK: - Corpus wire format

/// Top level of `priv/parity/v1/corpus.json`.
private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let lightSources: [String]
    let scenarios: [ParityScenario]

    enum CodingKeys: String, CodingKey {
        case algorithmVersion = "algorithm_version"
        case scorer
        case selection
        case missingPolicy = "missing_policy"
        case lightSources = "light_sources"
        case scenarios
    }
}

private struct ParityScenario: Decodable {
    let id: String
    let weights: ParityWeights
    let target: ParityVector
    let palette: [ParityPaletteEntry]
    let expected: ParityExpected
}

/// Weights keyed by raw light-source name; keys outside
/// `LightingCondition` (e.g. `ultraviolet`) are ignored, mirroring the
/// Elixir `filter_weights/1` behavior.
private struct ParityWeights: Decodable {
    let channels: [String: Double]

    init(from decoder: Decoder) throws {
        channels = try decoder.singleValueContainer().decode([String: Double].self)
    }

    var channelWeights: ChannelWeights {
        var weights = ChannelWeights()
        for condition in LightingCondition.all {
            weights[condition: condition] = channels[condition.rawValue] ?? 0
        }
        return weights
    }
}

private struct ParityVector: Decodable {
    let hexColor: String
    let channels: [String: Double]

    enum CodingKeys: String, CodingKey {
        case hexColor = "hex_color"
        case channels
    }

    var vector: TargetResponseVector {
        var brightness: [LightingCondition: Double] = [:]
        for condition in LightingCondition.all {
            brightness[condition] = channels[condition.rawValue]
        }
        return TargetResponseVector(brightness)
    }
}

private struct ParityPaletteEntry: Decodable {
    let hexColor: String
    let channels: [String: Double]

    enum CodingKeys: String, CodingKey {
        case hexColor = "hex_color"
        case channels
    }

    var color: PaletteColor {
        var responses: [LightingCondition: IlluminationResponse] = [:]
        for (key, value) in channels {
            if let condition = LightingCondition(rawValue: key) {
                responses[condition] = IlluminationResponse(brightness: value)
            }
        }
        return PaletteColor(
            id: 0,
            hex: hexColor,
            rgb: RGBColor(hex: hexColor)!,
            responses: responses
        )
    }
}

private struct ParityExpected: Decodable {
    let scores: [ParityCandidateScore]
    let selectedIndex: Int?
    let selectedHexColor: String?
    let error: Double?
    let tieBroke: Bool?
    let tiedIndices: [Int]

    enum CodingKeys: String, CodingKey {
        case scores
        case selectedIndex = "selected_index"
        case selectedHexColor = "selected_hex_color"
        case error
        case tieBroke = "tie_broke"
        case tiedIndices = "tied_indices"
    }
}

private struct ParityCandidateScore: Decodable {
    let index: Int
    let score: ParityScore
}

/// A per-candidate score: a JSON number, or the string `"excluded"`.
private enum ParityScore: Decodable {
    case value(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
        } else if let raw = try? container.decode(String.self), raw == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(
                in: container,
                debugDescription: "Parity score must be a number or \"excluded\""
            )
        }
    }

    var isExcluded: Bool {
        if case .excluded = self { return true }
        return false
    }
}

private extension ScorerResult {
    var isExcluded: Bool {
        if case .excluded = self { return true }
        return false
    }
}

private extension ChannelWeights {
    subscript(condition condition: LightingCondition) -> Double {
        get { weight(for: condition) }
        set {
            switch condition {
            case .white: white = newValue
            case .red: red = newValue
            case .green: green = newValue
            case .blue: blue = newValue
            case .lps: lps = newValue
            }
        }
    }
}
